//! L4 reports fix 1: pagination against Django's real `Paginator.get_page` (vectors generated by the frozen
//! Python), the shared date parser pinned to frozen Python's Unicode digits, and `share` preconditions.
use chrono::NaiveDate;
use fb_core::Money;
use fb_core::reports::financial::share;
use fb_core::reports::params::{self, RangeInput};

fn day(text: &str) -> NaiveDate {
    NaiveDate::parse_from_str(text, "%Y-%m-%d").unwrap()
}

#[test]
fn page_numbers_match_django_paginator_vectors() {
    let vectors: Vec<serde_json::Value> = serde_json::from_str(include_str!("data/report_page_vectors.json")).unwrap();
    assert_eq!(vectors.len(), 90);
    for v in &vectors {
        let text = v["text"].as_str();
        let count = v["count"].as_u64().unwrap() as usize;
        let want = v["page"].as_u64().unwrap() as usize;
        assert_eq!(params::page_number(text, count, 3), want, "{:?} count {count}", text.map(|t| t.chars().take(12).collect::<String>()));
    }
}

#[test]
fn oversized_integer_is_told_apart_from_invalid_text() {
    use fb_core::py::{PyInt, py_int};
    assert_eq!(py_int("999999999999999999999999999999"), Some(PyInt::Large { negative: false }));
    assert_eq!(py_int("-999999999999999999999999999999"), Some(PyInt::Large { negative: true }));
    assert_eq!(py_int(" \u{662}_0 "), Some(PyInt::Small(20)));
    assert_eq!(py_int("1__0"), None);
    assert_eq!(py_int("\u{10d42}"), None);
    assert_eq!(py_int(""), None);
    assert_eq!(py_int("-"), None);
}

#[test]
fn every_form_date_caller_rejects_digits_newer_than_frozen_python() {
    // Garay digits (Unicode 16) in the year: Python 3.13 (Unicode 15.1) says "Enter a valid date." everywhere.
    let garay = "\u{10d42}\u{10d40}\u{10d42}\u{10d46}";
    for text in [format!("{garay}-10-31"), format!("10/31/{garay}"), format!("Oct 31 {garay}")] {
        assert_eq!(fb_core::py::form_date(&text).unwrap_err(), "Enter a valid date.", "{text}");
        assert!(fb_core::py::model_date(&text).is_err(), "{text}");
        let got = params::as_of(None, Some(&text), day("2026-10-29"));
        assert_eq!(got.unwrap_err().messages(), vec!["Enter a valid date."]);
    }
    // Digits Python 3.13 knows are still accepted.
    assert_eq!(fb_core::py::form_date("\u{662}\u{660}\u{662}\u{666}-10-31").unwrap(), day("2026-10-31"));
    let input = RangeInput { start: Some("\u{6f2}\u{6f0}\u{6f2}\u{6f6}-10-01"), end: Some("2026-10-31"), ..Default::default() };
    assert_eq!(params::range(&input, day("2026-10-29")).unwrap().start, Some(day("2026-10-01")));
}

#[test]
fn ledger_cross_field_rules_wait_for_every_field() {
    let today = day("2026-10-29");
    // Field errors come in field order and suppress the range rules.
    let input = RangeInput { preset: Some("bogus"), start: Some("bad"), ..Default::default() };
    let got = params::ledger_range(&input, Some("x"), Some("nope"), today).unwrap_err().messages();
    assert_eq!(
        got,
        vec![
            "Select a valid choice. bogus is not one of the available choices.",
            "Enter a valid date.",
            "Choose an account from the list.",
            "Select a valid choice. nope is not one of the available choices."
        ]
    );
    // With every field valid the range rule still runs.
    let input = RangeInput { preset: Some("custom"), ..Default::default() };
    assert_eq!(params::ledger_range(&input, None, Some(""), today).unwrap_err().messages(), vec!["Enter a \"To\" date for a custom range."]);
    let input = RangeInput { start: Some("2026-12-01"), end: Some("2026-01-01"), ..Default::default() };
    assert_eq!(
        params::ledger_range(&input, None, None, today).unwrap_err().messages(),
        vec!["The \"From\" date must not be after the \"To\" date."]
    );
}

#[test]
fn share_refuses_extremes_without_panicking() {
    let one = Money::from_cents(1);
    for (nets, total, settled) in [
        (vec![(1, one)], Money::from_cents(i128::MIN), one),
        (vec![(1, one)], Money::from_cents(-1), Money::from_cents(i128::MIN)),
        (vec![(1, Money::from_cents(-i128::MAX)), (2, Money::from_cents(i128::MAX))], Money::from_cents(-1), one),
        (vec![(1, Money::from_cents(i128::MAX)), (2, Money::from_cents(i128::MAX))], Money::from_cents(3), one),
    ] {
        let got = std::panic::catch_unwind(|| share(&nets, total, settled)).expect("no panic");
        assert_eq!(got.unwrap_err().messages(), vec!["Report amounts exceed supported totals."]);
    }
    // Ordinary shares are unchanged: 1/3 of 10.00 split 3.34 / 3.33 / 3.33 by remainder, ties to the lower key.
    let nets = [(1, Money::from_cents(334)), (2, Money::from_cents(333)), (3, Money::from_cents(333))];
    let got = share(&nets, Money::from_cents(1000), Money::from_cents(500)).unwrap();
    assert_eq!(got.values().map(|m| m.cents()).sum::<i128>(), 500);
}
